(1, 0, 'بعد نزع الإلكترون الأول تبقى الشحنة الموجبة نفسها لعدد أقل من الإلكترونات، فيزيد جذبها لكل إلكترون.', '["","الإلكترون الثاني أقرب أو مساوٍ في البعد.","الكثافة تزيد لا تنقص.","كتلة الإلكترون أصغر بكثير من النواة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T05:55:02.414Z"}'::jsonb),
